settings.custom_liquid:
{%- comment -%} 排除的系列（handle），逗号分隔 {%- endcomment -%}
{%- assign excluded = 'flash-sale' | split: ',' -%}

{%- assign hide = false -%}
{%- for c in product.collections -%}
  {%- if excluded contains c.handle -%}{%- assign hide = true -%}{%- endif -%}
{%- endfor -%}
{%- comment -%} 带 Gift tag 的赠品不显示 {%- endcomment -%}
{%- if product.tags contains 'Gift' -%}{%- assign hide = true -%}{%- endif -%}

{%- unless hide -%}
  <div class="mt-promo">
    <svg class="mt-promo__ico" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
      <path d="M3 8h18v11a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V8Z"/><path d="M3 8 5 4h14l2 4"/><path d="M12 8v12"/>
    </svg>
    <span class="mt-promo__main">Buy 2 save 15% &middot; 4 save 20% &middot; 6 save 30%</span>
  </div>

  <style>
    .shopify-block:has(> .mt-promo){ margin: 0; padding: 0; }

    .mt-promo{
      display: inline-flex;
      align-items: center;
      gap: 10px;
      margin: 16px 0 20px;
      padding: 10px 13px;
      background: #FFF6EC;
      border: 1px solid #FBE3CB;
      border-left: 3px solid #FF8300;
      border-radius: 2px;
    }
    .mt-promo__ico{ width: 16px; height: 16px; flex: 0 0 16px; color: #B04E0C; }
    .mt-promo__main{
      font-size: 15px;
      font-weight: 600;
      line-height: 1.35;
      color: #140F0F;
    }

    @media (max-width: 480px){
      .mt-promo{ display: flex; padding: 10px 12px; margin: 8px 0 18px; }
      .mt-promo__ico{ display: none; }
      .mt-promo__main{ font-size: 14px; }
    }
  </style>
{%- endunless -%}

